// The web app's manifest (public/manifest.webmanifest): what lets a browser
// offer to install it. The icons it names are generated by
// scripts/brand/build-icons.js; this holds the manifest to what is on disk and
// to the design tokens.
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { light } from '@core/design/tokens.ts';

const WEB = join(dirname(fileURLToPath(import.meta.url)), '..');
const manifest = JSON.parse(readFileSync(join(WEB, 'public/manifest.webmanifest'), 'utf8'));

/** The width, height and colour type a PNG declares in its header. */
function pngHeader(file) {
  const bytes = readFileSync(join(WEB, 'public', file));
  expect(bytes.subarray(1, 4).toString('latin1')).toBe('PNG');
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20), colourType: bytes[25] };
}

describe('the web app manifest', () => {
  it('names the app, opens it on the home screen, and runs it in its own window', () => {
    expect(manifest).toMatchObject({
      name: 'DementiaGuide AI',
      short_name: 'DementiaGuide',
      lang: 'en-NZ',
      start_url: '/#/app/home',
      scope: '/',
      display: 'standalone',
    });
    expect(manifest.short_name.length).toBeLessThanOrEqual(13); // fits under a home-screen icon
    expect(manifest.description.length).toBeGreaterThan(20);
  });

  it('takes its colours from the design tokens', () => {
    expect(manifest.background_color).toBe(light.bg);
    expect(manifest.theme_color).toBe(light.primary);
  });

  it('offers the sizes browsers ask for: 192 and 512 for any use, and a maskable 512', () => {
    const summary = manifest.icons.map((i) => `${i.sizes} ${i.purpose}`);
    expect(summary).toEqual(['192x192 any', '512x512 any', '512x512 maskable']);
    expect(manifest.icons.every((i) => i.type === 'image/png')).toBe(true);
  });

  it.each(manifest.icons)('$src is on disk at the size it declares', (icon) => {
    const [width, height] = icon.sizes.split('x').map(Number);
    const header = pngHeader(icon.src);
    expect({ width: header.width, height: header.height }).toEqual({ width, height });
  });

  it('has no transparency in the maskable icon, because the device cuts its own shape from it', () => {
    const maskable = manifest.icons.find((i) => i.purpose === 'maskable');
    expect(pngHeader(maskable.src).colourType).toBe(2); // RGB, no alpha
    const any = manifest.icons.find((i) => i.purpose === 'any');
    expect(pngHeader(any.src).colourType).toBe(6); // RGBA: the rounded tile has clear corners
  });

  it('is linked from the page', () => {
    const html = readFileSync(join(WEB, 'index.html'), 'utf8');
    expect(html).toContain('<link rel="manifest" href="/manifest.webmanifest" />');
  });
});
